pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.deal(alice, 10 ether);
        vm.prank(alice);
        c.addToBalance{value: 3}();
        vm.prank(alice);
        c.addToBalance{value: 3}();
        assertTrue(c.getBalance(alice) == 6);
    }
}
